<?php
namespace App\Domain\AI\Knowledge\Services;use App\Domain\AI\Agents\Services\AiLifecycleAuthorization;use App\Domain\AI\Jobs\AiJobDispatcher;use App\Domain\AI\Knowledge\Enums\{KnowledgeIndexStatus,KnowledgeSourceStatus,KnowledgeVersionStatus};use App\Domain\AI\Knowledge\Jobs\BuildKnowledgeIndexJob;use App\Domain\AI\Knowledge\Models\{KnowledgeIndex,KnowledgeSource,KnowledgeSourceVersion};use App\Models\User;use Illuminate\Support\Facades\DB;
final class RequestKnowledgeIndexingService
{
 public function __construct(private AiLifecycleAuthorization$auth,private AiJobDispatcher$dispatcher){}
 public function request(User$actor,KnowledgeSource$source,KnowledgeSourceVersion$version):KnowledgeIndex{$index=DB::transaction(function()use($actor,$source,$version){$a=$this->auth->authorize($actor);$s=KnowledgeSource::query()->lockForUpdate()->findOrFail($source->id);if($s->status!==KnowledgeSourceStatus::Active)throw new \App\Domain\AI\Knowledge\Exceptions\ArchivedKnowledgeSourceException('Archived knowledge cannot be indexed.');$v=KnowledgeSourceVersion::query()->lockForUpdate()->findOrFail($version->id);if((int)$v->knowledge_source_id!==(int)$s->id)throw new \DomainException('Knowledge version does not belong to source.');if($v->status!==KnowledgeVersionStatus::Approved)throw new \DomainException('Only approved knowledge can be prepared.');$existing=KnowledgeIndex::query()->where('knowledge_source_version_id',$v->id)->lockForUpdate()->first();if($existing){if(!hash_equals($existing->content_checksum,$v->checksum))throw new \DomainException('Knowledge index checksum is stale.');return$existing;}$index=new KnowledgeIndex();$index->knowledge_source_id=$s->id;$index->knowledge_source_version_id=$v->id;$index->status=KnowledgeIndexStatus::Pending;$index->schema_version='1.0';$index->content_checksum=$v->checksum;$index->chunk_count=0;$index->requested_by_user_id=$a->actorUserId;$index->requested_at=now();$index->save();return$index;});if($index->status!==KnowledgeIndexStatus::Ready)DB::afterCommit(fn()=>$this->dispatcher->dispatch(fn(int$tenantId)=>new BuildKnowledgeIndexJob($tenantId,$index->id)));return$index;}
}
